	@Test
	void recognizedShapesProbeNativeAndGenericSourcesBeforeTheResidual() {
		List<ExpressionCase> cases = List.of(
				new ExpressionCase(contains(), Operation.CONTAINS),
				new ExpressionCase(function(FN.CONTAINS, lower(Var.of("v")), constant("needle")),
						Operation.CONTAINS),
				new ExpressionCase(function(FN.STARTS_WITH, lower(Var.of("v")), lower(constant("NEEDLE"))),
						Operation.STARTS_WITH),
				new ExpressionCase(new Compare(lower(Var.of("v")), lower(constant("NEEDLE")),
						Compare.CompareOp.EQ), Operation.EQUALS),
				new ExpressionCase(new Compare(lower(constant("NEEDLE")), lower(Var.of("v")),
						Compare.CompareOp.EQ), Operation.EQUALS),
				new ExpressionCase(function(FN.CONTAINS, lower(Var.of("v")),
						new Var("needle", VF.createLiteral("needle"))), Operation.CONTAINS));
		for (ExpressionCase test : cases) {
			RecordingSource source = new RecordingSource();
			ValueExpr prepared = prepare(test.expression);
			AtomicInteger residualCalls = new AtomicInteger();
			LmdbNativeTruthEvaluator nativeGuard = LmdbLiteralTextFilter.guardNative(prepared, source, SLOTS,
					row -> {
						residualCalls.incrementAndGet();
						return LmdbNativeTruth.ERROR;
					});
			assertThat(nativeGuard.eval(slot -> 101L)).isEqualTo(LmdbNativeTruth.FALSE);
			assertProbe(source, 101L, test.operation);
			source.probes.clear();

			LmdbLiteral literal = source.lazyLiteral(41L);
			QueryValueEvaluationStep genericGuard = LmdbLiteralTextFilter.guardGeneric(prepared, source, CONTEXT,
					bindings -> {
						residualCalls.incrementAndGet();
						return BooleanLiteral.TRUE;
					});
			assertThat(genericGuard.evaluate(bindings(literal))).isEqualTo(BooleanLiteral.FALSE);
			assertProbe(source, source.admittedId, test.operation);
			assertThat(source.lookedUpValues).hasSize(1);
			assertThat(source.lookedUpValues.get(0)).isSameAs(literal);
			assertThat(literal.isInitialized()).as("probing must not read a lazy label").isFalse();
			assertThat(residualCalls).hasValue(0);
		}
	}

	@Test
	void bothEvaluationStrategiesInstallTheGenericGuard() {
		for (boolean nativeStrategy : List.of(false, true)) {
			RecordingSource source = new RecordingSource();
			DefaultEvaluationStrategy strategy = strategy(source, nativeStrategy);
			ValueExpr expression = contains();
			Filter filter = new Filter(new SingletonSet(), expression);
			QueryValueEvaluationStep step = strategy.precompile(expression, CONTEXT);
			assertThat(filter.getCondition()).as("preparation must retain the pinned root function")
					.isNotSameAs(expression);
			LmdbLiteral literal = source.lazyLiteral(41L);
			assertThat(step.evaluate(bindings(literal))).isEqualTo(BooleanLiteral.FALSE);
			assertProbe(source, source.admittedId, Operation.CONTAINS);
			assertThat(literal.isInitialized()).isFalse();
		}
	}

